// Checks the desktop app's hardening (Plan.md P8.3, ADR-0017).
//
//   node scripts/tauri-hardening.mjs
//
// Fails if any of these changes:
// - the CSP, `withGlobalTauri` or any other `app.security` setting in tauri.conf.json
// - a window's devtools, URL or scheme, or the dev URL
// - the capabilities: one file, `main.json`, granting exactly the app's own commands
// - the app's command manifest: build.rs's `COMMANDS`, the empty default permission that
//   keeps the ACL on for app commands, and the `allow-`/`deny-<command>` files tauri-build
//   generates into `permissions/autogenerated/` (committed), each exactly its template
// - the IPC contract fixture (`tests/ipc-contract.json`), which must list exactly
//   `COMMANDS`, in order
// - tauri's resolved features, which `cargo tree` reports; `devtools`, `dynamic-acl` and
//   `custom-protocol` are named as never allowed
// - fleet-client's resolved features in the app: exactly `CLIENT_FEATURES`, none (ADR-0020,
//   S57)
//
// The expected values live here on purpose: changing a hardening setting means changing
// this check too, deliberately, with an ADR. A new command goes into `COMMANDS` here and
// in build.rs, its `allow-<command>` into `main.json`, and its entry into the fixture.
//
// Exits with 1 on any problem, or if cargo's output can't be read. Run through
// `just tauri-check`, which needs Rust for `cargo tree`; the frontend CI job that runs
// `just scripts-test` has none, so the tests check the parsing and the committed files.
// Tests: scripts/tauri-hardening.test.mjs.
import { spawnSync } from "node:child_process";
import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath, pathToFileURL } from "node:url";
import { isDeepStrictEqual } from "node:util";

/** P8.3's CSP, exactly. Relaxing it needs an ADR. */
export const CSP =
  "default-src 'self'; img-src 'self' data:; style-src 'self'; connect-src ipc: http://ipc.localhost";

/** The app's own commands, as build.rs lists them (P8.4; the accounts' and the opener in P9.8, ADR-0018). */
export const COMMANDS = [
  "server_profile",
  "set_server_profile",
  "check_server",
  "login",
  "login_mfa",
  "logout",
  "register",
  "step_up",
  "mfa_enroll",
  "mfa_confirm",
  "mfa_reset",
  "me",
  "change_password",
  "sessions",
  "revoke_session",
  "users",
  "patch_user",
  "invites",
  "create_invite",
  "revoke_invite",
  "start_link",
  "link_status",
  "create_offline_account",
  "accounts",
  "accounts_awaiting_approval",
  "account",
  "delete_account",
  "approve_account",
  "refuse_account",
  "relink_account",
  "account_grants",
  "create_grant",
  "change_grant",
  "revoke_grant",
  "open_verification_link",
  "watch_events",
  "bots",
  "bot",
  "modes",
  "patch_bot",
  "set_bot_mode",
  "start_bot",
  "stop_bot",
  "restart_bot",
  "reset_bot",
  "resume_bot",
];

/** The whole of `app.security`. */
const SECURITY = {
  csp: CSP,
  // The served CSP is exactly CSP: no hashes or nonces appended (ADR-0017).
  dangerousDisableAssetCspModification: true,
  freezePrototype: true,
  capabilities: ["main"],
};

/** Vite's dev server, the only other origin a dev build may show (the navigation guard). */
const DEV_URL = "http://localhost:1420";

/** Window settings that would open devtools, load other content or change the origin. */
const FORBIDDEN_WINDOW_KEYS = ["devtools", "url", "useHttpsScheme"];

/** The keys a capability may have; anything else (remote, platforms, webviews…) fails. */
const CAPABILITY_KEYS = ["$schema", "description", "identifier", "windows", "permissions"];

/** tauri's features, as `cargo tree` resolves `wry` and `compression`. */
const TAURI_FEATURES = ["compression", "tauri-runtime-wry", "webkit2gtk", "webview2-com", "wry"];

/** Features that must never appear, each named in its own message. */
const FORBIDDEN_FEATURES = ["devtools", "dynamic-acl", "custom-protocol"];

/** The desktop crate's folder, relative to the repository's root. */
const SRC_TAURI = path.join("apps", "desktop", "src-tauri");

/** The `cargo tree` arguments: tauri's line with its resolved features, dev edges left out. */
export const CARGO_TREE_ARGS = [
  "tree",
  "--package",
  "afkfleet-desktop",
  "--edges",
  "no-dev",
  "--target",
  "x86_64-pc-windows-msvc",
  "--invert",
  "tauri",
  "--depth",
  "0",
  "--prefix",
  "none",
  "--format",
  "{p}|{f}",
];

/** The same for fleet-client's line, as the desktop app resolves it, dev edges left out. */
export const CLIENT_TREE_ARGS = CARGO_TREE_ARGS.map((arg) =>
  arg === "tauri" ? "fleet-client" : arg,
);

/**
 * fleet-client's features in the desktop app, exactly: none. A feature joins this list
 * only with an ADR, so a new one fails the check until it's decided (ADR-0020, S57).
 */
const CLIENT_FEATURES = [];

/** Each capability permission that grants one of the app's own commands. */
function commandGrants() {
  return COMMANDS.map((command) => `allow-${command.replaceAll("_", "-")}`);
}

function show(value) {
  return value === undefined ? "unset" : JSON.stringify(value);
}

/** Checks tauri.conf.json's parsed content. Returns one message per problem. */
export function checkConfig(config) {
  const problems = [];
  const app = config?.app ?? {};
  if (app.withGlobalTauri !== false) {
    problems.push(`app.withGlobalTauri is ${show(app.withGlobalTauri)}, expected false`);
  }
  const security = app.security ?? {};
  for (const key of new Set([...Object.keys(SECURITY), ...Object.keys(security)])) {
    if (!isDeepStrictEqual(security[key], SECURITY[key])) {
      problems.push(
        key in SECURITY
          ? `app.security.${key} is ${show(security[key])}, expected ${show(SECURITY[key])}`
          : `app.security.${key} must not be set`,
      );
    }
  }
  for (const [index, window] of (app.windows ?? []).entries()) {
    for (const key of FORBIDDEN_WINDOW_KEYS) {
      if (key in window) {
        problems.push(`app.windows[${index}].${key} must not be set`);
      }
    }
  }
  if (config?.build?.devUrl !== DEV_URL) {
    problems.push(`build.devUrl is ${show(config?.build?.devUrl)}, expected ${show(DEV_URL)}`);
  }
  return problems;
}

/**
 * Checks the capabilities folder, given as `{ name, text }` entries. Returns one message per
 * problem: there must be exactly `main.json`, for window `main`, granting exactly the app's
 * own commands, so no core or plugin permission.
 */
export function checkCapabilities(files) {
  const problems = files
    .filter(({ name }) => name !== "main.json")
    .map(({ name }) => `capabilities/${name} must not exist: main.json is the only capability`);
  const main = files.find(({ name }) => name === "main.json");
  if (main === undefined) {
    return [...problems, "capabilities/main.json is missing"];
  }
  let capability;
  try {
    capability = JSON.parse(main.text);
  } catch (error) {
    return [...problems, `capabilities/main.json isn't JSON: ${error.message}`];
  }
  for (const key of Object.keys(capability)) {
    if (!CAPABILITY_KEYS.includes(key)) {
      problems.push(`capabilities/main.json: ${key} must not be set`);
    }
  }
  const expected = { identifier: "main", windows: ["main"], permissions: commandGrants() };
  for (const [key, value] of Object.entries(expected)) {
    if (!isDeepStrictEqual(capability[key], value)) {
      problems.push(
        `capabilities/main.json: ${key} is ${show(capability[key])}, expected ${show(value)}`,
      );
    }
  }
  return problems;
}

/** build.rs's command list: `const COMMANDS: &[&str] = &[…];`. */
const COMMANDS_CONST = /^const COMMANDS: &\[&str\] = &\[([^\]]*)\];$/m;

/** Checks build.rs's text. Returns one message per problem. */
export function checkCommands(buildScript) {
  const match = COMMANDS_CONST.exec(buildScript.replaceAll("\r\n", "\n"));
  if (match === null) {
    return ["build.rs has no `const COMMANDS: &[&str] = &[…];` line"];
  }
  const listed = match[1]
    .split(",")
    .map((item) => item.trim())
    .filter((item) => item !== "")
    .map((item) => item.replace(/^"(.*)"$/, "$1"));
  return isDeepStrictEqual(listed, COMMANDS)
    ? []
    : [`build.rs lists the commands ${show(listed)}, expected ${show(COMMANDS)}`];
}

/** The default permission's lines, comments and blank lines aside. */
const DEFAULT_PERMISSION = [/^\[default\]$/, /^description = ".*"$/, /^permissions = \[\]$/];

/** The folder tauri-build writes each command's permissions into. */
const GENERATED = "autogenerated";

/**
 * The permission file tauri-build 2.7.2 writes for `command`, exactly as tauri-utils
 * 2.10.1's `autogenerate_command_permissions` formats it: no license header, no schema
 * reference, LF line ends. Its `allow-` permission grants the command, its `deny-`
 * permission refuses it.
 */
export function generatedPermission(command) {
  const slug = command.replaceAll("_", "-");
  return `# Automatically generated - DO NOT EDIT!

[[permission]]
identifier = "allow-${slug}"
description = "Enables the ${command} command without any pre-configured scope."
commands.allow = ["${command}"]

[[permission]]
identifier = "deny-${slug}"
description = "Denies the ${command} command without any pre-configured scope."
commands.deny = ["${command}"]
`;
}

/**
 * Checks `permissions/autogenerated/`'s entries: exactly one `<command>.toml` per command,
 * each byte-equal to its template, and nothing else, so neither an edited grant nor a file
 * left by a removed command (tauri-build never deletes one) can pass.
 */
function checkGenerated(entries) {
  const expected = new Map(COMMANDS.map((command) => [`${command}.toml`, command]));
  const problems = [];
  for (const entry of entries) {
    const command = expected.get(entry.name);
    if (command === undefined) {
      problems.push(
        `permissions/${GENERATED}/${entry.name} must not exist: it isn't a command build.rs lists`,
      );
    } else if (entry.text !== generatedPermission(command)) {
      problems.push(`permissions/${GENERATED}/${entry.name} isn't tauri-build's generated file`);
    }
  }
  for (const name of expected.keys()) {
    if (!entries.some((entry) => entry.name === name)) {
      problems.push(`permissions/${GENERATED}/${name} is missing: build the desktop crate`);
    }
  }
  return problems;
}

/**
 * Checks the permissions folder, given as `{ name, text }` file and `{ name, entries }`
 * folder entries. Returns one message per problem: there must be exactly `default.toml`,
 * an empty default permission, and the generated folder holding exactly each command's
 * file.
 */
export function checkPermissions(files) {
  const problems = files
    .filter(({ name }) => name !== "default.toml" && name !== GENERATED)
    .map(
      ({ name }) =>
        `permissions/${name} must not exist: default.toml and ${GENERATED}/ are the only ones`,
    );
  const generated = files.find(({ name }) => name === GENERATED);
  if (generated?.entries === undefined) {
    problems.push(
      `permissions/${GENERATED}/ must be a folder holding the generated command permissions`,
    );
  } else {
    problems.push(...checkGenerated(generated.entries));
  }
  const file = files.find(({ name }) => name === "default.toml");
  if (file?.text === undefined) {
    return [...problems, "permissions/default.toml is missing: without it, the ACL is off"];
  }
  const lines = file.text
    .split("\n")
    .map((line) => line.trimEnd())
    .filter((line) => line !== "" && !line.startsWith("#"));
  const matches =
    lines.length === DEFAULT_PERMISSION.length &&
    lines.every((line, index) => DEFAULT_PERMISSION[index]?.test(line));
  if (!matches) {
    problems.push(
      "permissions/default.toml must hold only `[default]`, a description and " +
        "`permissions = []`: no other permission, set or grant",
    );
  }
  return problems;
}

/**
 * Checks the IPC contract fixture's text: its `commands` must name exactly `COMMANDS`, in
 * order, so a command can't be added without its contract entry. Returns one message per
 * problem.
 */
export function checkContract(text) {
  let fixture;
  try {
    fixture = JSON.parse(text);
  } catch (error) {
    return [`tests/ipc-contract.json isn't JSON: ${error.message}`];
  }
  if (!Array.isArray(fixture?.commands)) {
    return ["tests/ipc-contract.json has no `commands` list"];
  }
  const listed = fixture.commands.map((entry) => entry?.command);
  return isDeepStrictEqual(listed, COMMANDS)
    ? []
    : [`tests/ipc-contract.json lists the commands ${show(listed)}, expected ${show(COMMANDS)}`];
}

/** Checks `cargo tree`'s output for tauri's features. Returns one message per problem. */
export function checkFeatures(output) {
  const lines = output
    .split("\n")
    .map((line) => line.trimEnd())
    .filter((line) => line !== "");
  const match = lines.length === 1 ? /^tauri v\S+\|(.*)$/.exec(lines[0] ?? "") : null;
  if (match === null) {
    return [`cargo tree's output can't be read: \`${output.trim()}\``];
  }
  const features = (match[1] ?? "").split(",").filter((feature) => feature !== "");
  const problems = FORBIDDEN_FEATURES.filter((feature) => features.includes(feature)).map(
    (feature) => `tauri's \`${feature}\` feature is on, but it must never be`,
  );
  const unexpected = features.filter(
    (feature) => !TAURI_FEATURES.includes(feature) && !FORBIDDEN_FEATURES.includes(feature),
  );
  const missing = TAURI_FEATURES.filter((feature) => !features.includes(feature));
  if (unexpected.length > 0) {
    problems.push(`tauri has features the check doesn't expect: ${unexpected.join(", ")}`);
  }
  if (missing.length > 0) {
    problems.push(`tauri lacks features the check expects: ${missing.join(", ")}`);
  }
  return problems;
}

/**
 * Checks `cargo tree`'s output for fleet-client's features: exactly `expected`, by default
 * `CLIENT_FEATURES`. Returns one message per problem.
 */
export function checkClientFeatures(output, expected = CLIENT_FEATURES) {
  const lines = output
    .split("\n")
    .map((line) => line.trimEnd())
    .filter((line) => line !== "");
  const match = lines.length === 1 ? /^fleet-client v\S+ \(.*\)\|(.*)$/.exec(lines[0] ?? "") : null;
  if (match === null) {
    return [`cargo tree's output for fleet-client can't be read: \`${output.trim()}\``];
  }
  const features = (match[1] ?? "").split(",").filter((feature) => feature !== "");
  const problems = features
    .filter((feature) => !expected.includes(feature))
    .map(
      (feature) =>
        `fleet-client's \`${feature}\` feature is on in the desktop app, but the check doesn't list it: a feature joins only with an ADR (ADR-0020, S57)`,
    );
  const missing = expected.filter((feature) => !features.includes(feature));
  if (missing.length > 0) {
    problems.push(`fleet-client lacks features the check expects: ${missing.join(", ")}`);
  }
  return problems;
}

/**
 * The entries of `dir`: `{ name, text }` for a file, `{ name, entries }` for a folder, read
 * the same way; none if it doesn't exist. A folder is never read as a file.
 */
export function readFolder(dir) {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  return entries.map((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory()
      ? { name: entry.name, entries: readFolder(full) }
      : { name: entry.name, text: readFileSync(full, "utf8") };
  });
}

/** Checks the committed files under `root` (everything but `cargo tree`). */
export function checkRepoFiles(root) {
  const dir = path.join(root, SRC_TAURI);
  let config;
  try {
    config = JSON.parse(readFileSync(path.join(dir, "tauri.conf.json"), "utf8"));
  } catch (error) {
    return [`tauri.conf.json can't be read: ${error.message}`];
  }
  return [
    ...checkConfig(config),
    ...checkCapabilities(readFolder(path.join(dir, "capabilities"))),
    ...checkCommands(readFileSync(path.join(dir, "build.rs"), "utf8")),
    ...checkPermissions(readFolder(path.join(dir, "permissions"))),
    ...checkContractFile(path.join(dir, "tests", "ipc-contract.json")),
  ];
}

/** Checks the contract fixture at `file`; a missing or unreadable one is a problem too. */
function checkContractFile(file) {
  let text;
  try {
    text = readFileSync(file, "utf8");
  } catch (error) {
    return [`tests/ipc-contract.json can't be read: ${error.message}`];
  }
  return checkContract(text);
}

function main() {
  const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
  const problems = checkRepoFiles(root);
  const result = spawnSync("cargo", CARGO_TREE_ARGS, { cwd: root, encoding: "utf8" });
  if (result.error !== undefined || result.status !== 0) {
    console.error(result.stderr ?? "");
    problems.push(`cargo tree failed: ${result.error?.message ?? `exit code ${result.status}`}`);
  } else {
    problems.push(...checkFeatures(result.stdout));
  }
  const client = spawnSync("cargo", CLIENT_TREE_ARGS, { cwd: root, encoding: "utf8" });
  if (client.error !== undefined || client.status !== 0) {
    console.error(client.stderr ?? "");
    problems.push(`cargo tree failed: ${client.error?.message ?? `exit code ${client.status}`}`);
  } else {
    problems.push(...checkClientFeatures(client.stdout));
  }
  for (const problem of problems) {
    console.error(problem);
  }
  if (problems.length > 0) {
    console.error("the desktop app's hardening changed (Plan.md P8.3, ADR-0017)");
    return 1;
  }
  console.log("the desktop app's hardening is as pinned");
  return 0;
}

if (process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = main();
}
